/**
 * 角色名类型定义，用于 items.js 中 character 字段的 IDE 自动补全
 * 修改 characters.js 后需同步更新此文件
 */

// 初代
type CharacterName_Gen1 = '星宫莓' | '雾矢葵' | '紫吹兰' | '有栖川乙女' | '藤堂尤里卡'
  | '北大路樱' | '一之濑枫' | '神崎美月' | '夏树未来' | '神谷紫苑' | '三轮光'
  | '音城塞拉' | '音城诺艾尔' | '冴草纪伊' | '风沢空' | '姬里玛利亚' | '光石织姬'
  | '星宫苹果' | '星宫赖智' | '凉川直人' | '乔尼·别府';

// 明代
type CharacterName_Gen2 = '大空明' | '冰上堇' | '新条雏姬' | '红林珠璃' | '黑泽凛'
  | '天羽圆香' | '大地乃野' | '白桦丽莎' | '堂岛妮娜' | '服部优' | '栗栖心音'
  | '藤原雅' | '濑名翼' | '四叶春';

// 星代
type CharacterName_Star = '虹野梦' | '七仓小春' | '樱庭劳拉' | '早乙女亚子' | '香澄真昼'
  | '花园绮罗' | '双叶亚里亚' | '二阶堂柚子' | '白银莉莉' | '骑咲礼' | '艾尔莎·福特'
  | '香澄夜空' | '如月翼' | '晴香露卡' | '五十岚望' | '吉良彼方' | '结城昂'
  | '香澄朝阳' | '诸星辉';

// 友代
type CharacterName_Friends = '友希爱音' | '凑美绪' | '蝶乃舞花' | '日向绘麻'
  | '神城卡莲' | '明日香未来' | '白百合辉夜' | '白百合咲夜' | '天翔响'
  | '艾莉西亚·夏洛特' | '春风若叶';

// 大游行 / 行星 / Academy / 其他
type CharacterName_Other = '姬石来希' | '音羽舞樱' | '珠树琉璃' | '梅小路响子'
  | '本谷栞' | '月城爱弓' | '栗六杏' | '阳明咲' | '糸井纱良'
  | '姫乃Mieru' | '真未梦Meh' | '和央Parin' | '凛堂Taimu'
  | '其他';

/** 所有角色名联合类型，在 items.js 的 character 字段输入时 IDE 会给出补全提示 */
type CharacterName = CharacterName_Gen1 | CharacterName_Gen2 | CharacterName_Star
  | CharacterName_Friends | CharacterName_Other;

/** 商品类型 */
type GoodsType = '徽章' | '亚克力立牌' | '卡片' | '文件夹' | '毛绒玩偶';
